import argparse
import re
import shutil
from collections import Counter
from pathlib import Path

import jinja2
import yaml

from nextflow_generator import GENERATED_MARK as MODULE_MARK, NextflowGenerator

# First line of every generated file, used to know which files can be overwritten
GENERATED_MARK = "Generated by utils_biobb nextflow_wf_generator.py from the python workflow: do not edit by hand."
# Workflow outputs (output block) are stable since 25.10
NEXTFLOW_VERSION = ">=25.10.0"
NAMESPACE = "bioexcel"
# Global properties of the python workflows that are not block properties
WORKFLOW_PROPERTIES = {"working_dir_path", "can_write_console_log"}
# Block properties of the python workflows left out, with the binary_path of their step: the biocontainers have no MPI
MPI_PROPERTIES = {"mpi_bin", "mpi_np", "mpi_flags", "mpi_hostlist"}
# Module labels with resources to set in the workflow configuration: {label: comment}
LABEL_COMMENTS = {"process_medium": "Multithreaded blocks (num_threads = cpus): set cpus to the cores of your machine or node"}
# e2e test settings of tests/nextflow/run_test.sh per workflow: the runtime cuts of the python CI (python-reusable.yaml,
# docs/testing.md §1.5) as sed -E expressions on a copy of nextflow.config, and full workflow attempts for flaky lookups
TEST_SETTINGS = {
    "biobb_wf_amber_abc_setup": {"runtime": [r"s/nstlim: [0-9]+/nstlim: 100/g", r"s/maxcyc: [0-9]+/maxcyc: 50/g"]},
    "biobb_wf_amber_md_setup": {"runtime": [r"s/nstlim: [0-9]+/nstlim: 500/g", r"s/maxcyc: [0-9]+/maxcyc: 100/g"]},
    "biobb_wf_amber_md_setup_lig": {"runtime": [r"s/nstlim: [0-9]+/nstlim: 500/g", r"s/maxcyc: [0-9]+/maxcyc: 100/g"]},
    "biobb_wf_md_setup": {"runtime": [r"s/nsteps: [0-9]+/nsteps: 10/g"]},
    # Only the free MD: a blanket cut blows up the NPT run of the un-equilibrated system
    "biobb_wf_protein-complex_md_setup": {"runtime": [r"s/nsteps: 250000/nsteps: 10/g"]},
    # structure_check fetches the ligand names from a flaky API
    "biobb_wf_structure_checking": {"attempts": 3},
}
# Groovy keywords that can't be closure parameter names
GROOVY_KEYWORDS = {"as", "def", "else", "for", "if", "in", "new", "return", "switch", "while"}

IMPORT_RE = re.compile(r"^from (biobb_\w+)\.[\w.]+ import (\w+)")
CALL_RE = re.compile(r"(\w+)\(\*\*global_paths\[[\"'](\w+)[\"']\]")
LOG_RE = re.compile(r"global_log\.info\([\"'](\w+): (.+?)[\"']\)")
FLAG_RE = re.compile(r"^if conf\.properties\[[\"']global_properties[\"']\]\[[\"'](\w+)[\"']\]:$")
BLOCK_RE = re.compile(r"^(if|elif|else|for|while|with|try|except|finally)\b")


class NextflowWFGenerator():

    def __init__(self, yml_input_path, python_input_path, adapters_path, output_path, **kwargs):

        # check if yml_input_path exists
        if not Path(yml_input_path).exists():
            raise SystemExit('Unexisting YAML input path')
        self.yml_input_path = Path(yml_input_path)

        # check if python_input_path exists
        if not Path(python_input_path).exists():
            raise SystemExit('Unexisting Python input path')
        self.python_input_path = Path(python_input_path)

        # check if adapters_path exists
        if not Path(adapters_path).exists():
            raise SystemExit('Unexisting adapters path')
        self.adapters_path = Path(adapters_path)

        self.output_path = Path(output_path)
        self.output_path.mkdir(parents=True, exist_ok=True)
        # biobb_wf_<name> folder, parent of the python folder
        self.wf_path = self.python_input_path.resolve().parent.parent
        self.modules = {}

        template_env = jinja2.Environment(loader=jinja2.FileSystemLoader(str(Path(__file__).parent.joinpath("templates"))),
                                          keep_trailing_newline=True)
        self.main_template = template_env.get_template("wf_main.nf.j2")
        self.config_template = template_env.get_template("wf_nextflow.config.j2")
        self.readme_template = template_env.get_template("wf_README.md.j2")
        self.test_template = template_env.get_template("wf_run_test.sh.j2")

    def parseYAML(self):
        """ returns the global properties and the steps of the workflow.yml """

        with open(self.yml_input_path) as yml_file:
            wf_dict = yaml.safe_load(yml_file)
        global_properties = wf_dict.pop("global_properties", None) or {}
        return global_properties, wf_dict

    def parsePython(self):
        """ returns the package of every imported tool, the steps called (step, tool, flags) and their log descriptions """

        tools = {}
        calls = []
        descriptions = {}
        # Open blocks: (indentation, global property flag of an `if` or None for any other block)
        blocks = []
        for line in self.python_input_path.read_text().splitlines():
            code = line.strip()
            if not code or code.startswith('#'):
                continue
            indent = len(line) - len(line.lstrip())
            while blocks and blocks[-1][0] >= indent:
                blocks.pop()

            match = IMPORT_RE.match(code)
            if match and match.group(1) != 'biobb_common':
                tools[match.group(2)] = match.group(1)
            match = LOG_RE.search(code)
            if match:
                descriptions.setdefault(match.group(1), match.group(2))
            match = CALL_RE.search(code)
            if match:
                if any(flag is None for _, flag in blocks):
                    raise SystemExit(f"{match.group(2)} is called inside a loop or a condition that is not a global property: port this workflow by hand")
                calls.append((match.group(2), match.group(1), [flag for _, flag in blocks]))
            if BLOCK_RE.match(code):
                match = FLAG_RE.match(code)
                blocks.append((indent, match.group(1) if match else None))

        return tools, calls, descriptions

    def getModule(self, package, tool):
        """ returns the process name, inputs and outputs of a Nextflow module, from its meta.yml and main.nf """

        if (package, tool) in self.modules:
            return self.modules[(package, tool)]

        module_path = self.adapters_path.joinpath(package, tool)
        if not module_path.joinpath("main.nf").exists():
            raise SystemExit(f"Unexisting {module_path}/main.nf module")
        main = module_path.joinpath("main.nf").read_text()
        with open(module_path.joinpath("meta.yml")) as meta_file:
            meta = yaml.safe_load(meta_file)

        # Blocks without input files take only meta: the input is a single channel instead of a tuple
        input_tuple = meta["input"][0]
        inputs = [{"name": arg["name"], "optional": arg["optional"]} for arg in input_tuple[1:]] if isinstance(input_tuple, list) else []
        outputs = []
        for channel in meta["output"]:
            if channel[0]["name"] != "meta":
                continue
            arg = channel[1]
            default = re.search(r"outputs\.%s \?: '([^']*)'" % arg["name"], main)
            # Output file named <prefix>_<role>.<extension>
            role = re.search(r"^\s+%s = .*?\$\{prefix\}_(\w+)" % arg["name"], main, re.M)
            outputs.append({"name": arg["name"], "optional": arg["optional"], "default": default.group(1) if default else "directory", "role": role.group(1)})

        self.modules[(package, tool)] = {
            "package": package,
            "tool": tool,
            "path": module_path,
            "process": re.search(r"^process (\w+)", main, re.M).group(1),
            "label": re.search(r"^\s+label '(\w+)'", main, re.M).group(1),
            "inputs": inputs,
            "outputs": outputs,
        }
        return self.modules[(package, tool)]

    def getColumns(self, steps):
        """ returns the samplesheet column of every file: input of the workflow """

        files = []
        for entry in steps.values():
            for value in (entry.get("paths") or {}).values():
                if str(value).startswith("file:") and value not in files:
                    files.append(value)

        def sanitize(text):
            name = re.sub(r"\W+", "_", text).strip("_").lower()
            return f"file_{name}" if not name or name[0].isdigit() or name == "id" else name

        # File stem (structure.pdb -> structure), or the whole name when two files share it
        stems = Counter(sanitize(Path(value[5:]).stem) for value in files)
        return {value: sanitize(Path(value[5:]).stem) if stems[sanitize(Path(value[5:]).stem)] == 1 else sanitize(Path(value[5:]).name)
                for value in files}

    def getVariable(self, argument):
        """ returns a closure parameter name for an argument: input_gro_path -> gro """

        name = re.sub(r"_path$", "", re.sub(r"^input_", "", argument))
        return argument if name in GROOVY_KEYWORDS or not re.match(r"^[A-Za-z_]\w*$", name) else name

    def getSource(self, step, argument, steps, columns):
        """ returns the channel of a step argument ([meta, file] items), or None when it is not in the workflow.yml """

        value = (steps[step].get("paths") or {}).get(argument)
        if value is None:
            return None
        value = str(value)
        if value.startswith("file:"):
            return f"ch_samples.map {{ meta, files -> [meta, files.{columns[value]}] }}"
        if value.startswith("dependency/"):
            _, dep_step, dep_argument = value.split("/")
            if dep_step not in steps:
                raise SystemExit(f"{step}.{argument}: unexisting step {dep_step}")
            if dep_step not in self.called:
                raise SystemExit(f"{step}.{argument}: {dep_step} is not called as <block>(**global_paths[...]) in {self.python_input_path}: port this workflow by hand")
            # A dependency on an input of another step is the source of that input
            if dep_argument.startswith("input_"):
                return self.getSource(dep_step, dep_argument, steps, columns)
            return f"{dep_step.upper()}.out.{dep_argument}"
        raise SystemExit(f"{step}.{argument}: {value} is not a file: or dependency/ path")

    def getStep(self, step, tool, flags, tools, steps, columns, global_properties, description):
        """ returns the include, call, configuration and published outputs of a step """

        entry = steps[step]
        if tool not in tools:
            raise SystemExit(f"{step}: {tool} is not imported from a biobb package in {self.python_input_path}")
        module = self.getModule(tools[tool], entry["tool"])
        alias = step.upper()
        paths = entry.get("paths") or {}

        arguments = {arg["name"] for arg in module["inputs"] + module["outputs"]}
        for argument in paths:
            if argument not in arguments:
                raise SystemExit(f"{step}: {argument} is not an argument of {NAMESPACE}/{module['package']}/{module['tool']}")

        # Input channel: sources joined by meta in the module input order, [] for the optional files not given
        sources = []
        for arg in module["inputs"]:
            source = self.getSource(step, arg["name"], steps, columns)
            if source is None and not arg["optional"]:
                raise SystemExit(f"{step}: missing required input {arg['name']}")
            sources.append(source)
        given = [source for source in sources if source]
        if not module["inputs"]:
            lines = ["ch_samples.map { meta, _files -> meta }"]
        elif not given:
            lines = [f"ch_samples.map {{ meta, _files -> [meta, {', '.join('[]' for _ in sources)}] }}"]
        else:
            lines = [given[0]] + [f".join({source})" for source in given[1:]]
            if len(given) < len(sources):
                names = [self.getVariable(arg["name"]) for arg, source in zip(module["inputs"], sources) if source]
                values = [self.getVariable(arg["name"]) if source else "[]" for arg, source in zip(module["inputs"], sources)]
                lines.append(f".map {{ meta, {', '.join(names)} -> [meta, {', '.join(values)}] }}")
        # Steps run only when the global properties of their python `if` are true
        lines += [f".filter {{ params.{flag} }}" for flag in flags]
        call = f"{alias}({lines[0]})" if len(lines) == 1 else f"{alias}(\n        " + "\n            ".join(lines) + "\n    )"

        # Output extensions of the workflow.yml file names, when they are not the module default, and optional outputs
        extensions = {}
        for arg in module["outputs"]:
            if arg["name"] in paths:
                extension = Path(str(paths[arg["name"]])).suffix[1:] or "directory"
                if arg["optional"] or extension != arg["default"]:
                    extensions[arg["name"]] = extension
        produced_args = [arg for arg in module["outputs"] if not arg["optional"] or arg["name"] in paths]
        produced = [f"{alias}.out.{arg['name']}" for arg in produced_args]
        # Published file names without the <id>_ prefix (ext.prefix is <id>_<step>), folders ending in /
        files = []
        for arg in produced_args:
            extension = extensions.get(arg["name"], arg["default"])
            files.append(f"{step.lower()}_{arg['role']}" + ("/" if extension == "directory" else f".{extension}"))

        properties = {**global_properties, **(entry.get("properties") or {})}
        # Steps with MPI properties also set the MPI build of the binary (sander.MPI): use the block default
        if MPI_PROPERTIES & properties.keys():
            properties = {k: v for k, v in properties.items() if k not in MPI_PROPERTIES | {"binary_path"}}
        config = []
        if properties:
            config.append(f"ext.properties = {NextflowGenerator.groovyValue(properties)}")
        if extensions:
            config.append(f"ext.outputs = {NextflowGenerator.groovyValue(extensions)}")

        return {
            "name": step,
            "alias": alias,
            "module": module,
            "include": f"include {{ {module['process']} as {alias} }} from './modules/{NAMESPACE}/{module['package']}/{module['tool']}'",
            "description": description,
            "flags": flags,
            "call": call,
            "config": config,
            "files": files,
            "results": produced[0] + (f".mix({', '.join(produced[1:])})" if len(produced) > 1 else "") + f".map {{ meta, result -> [meta, '{step}', result] }}",
        }

    def getTitle(self):
        """ returns the first heading of the workflow README.md """

        readme_path = self.wf_path.joinpath("README.md")
        if readme_path.exists():
            for line in readme_path.read_text().splitlines():
                if line.startswith("# "):
                    return line[2:].strip()
        return self.wf_path.name

    def getSampleId(self):
        """ returns the id of the default samplesheet row: the workflow name without biobb_wf_ """

        return re.sub(r"^biobb_wf_", "", self.wf_path.name)

    def writeGenerated(self, file_name, content, folder=None, executable=False):
        """ writes a generated file (in the output folder by default), unless it exists and was not generated """

        file_path = (folder or self.output_path).joinpath(file_name)
        if file_path.exists() and GENERATED_MARK not in file_path.read_text():
            print(f"{file_path} not generated: it exists and was edited by hand")
            return
        file_path.parent.mkdir(parents=True, exist_ok=True)
        file_path.write_text(content)
        if executable:
            file_path.chmod(0o755)
        print(f"{file_path} has been properly generated")

    def copyModules(self, steps):
        """ copies the modules used by the workflow into modules/<namespace>/<package>/<block>, removing the old ones """

        modules_path = self.output_path.joinpath("modules", NAMESPACE)
        for main_path in modules_path.glob("*/*/main.nf"):
            if MODULE_MARK in main_path.read_text():
                shutil.rmtree(main_path.parent)
        for module in {step["module"]["path"]: step["module"] for step in steps}.values():
            module_path = modules_path.joinpath(module["package"], module["tool"])
            module_path.mkdir(parents=True, exist_ok=True)
            for file_name in ("main.nf", "meta.yml", "README.md"):
                shutil.copy2(module["path"].joinpath(file_name), module_path)
            print(f"{module_path} has been properly copied")
        for package_path in modules_path.glob("*"):
            if package_path.is_dir() and not any(package_path.iterdir()):
                package_path.rmdir()

    def copyInputs(self, columns):
        """ copies the input files of the python workflow and writes the default samplesheet, with one row """

        for value in columns:
            source = self.yml_input_path.parent.joinpath(value[5:])
            if not source.exists():
                raise SystemExit(f"Unexisting input file {source}")
            target = self.output_path.joinpath(value[5:])
            target.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(source, target)

        samplesheet_path = self.output_path.joinpath("samplesheet.csv")
        if samplesheet_path.exists():
            print(f"{samplesheet_path} not generated: it already exists")
            return
        samplesheet_path.write_text(",".join(["id"] + list(columns.values())) + "\n"
                                    + ",".join([self.getSampleId()] + [value[5:] for value in columns]) + "\n")
        print(f"{samplesheet_path} has been properly generated")

    def launch(self):
        """ launch function for NextflowWFGenerator """

        global_properties, steps = self.parseYAML()
        tools, calls, descriptions = self.parsePython()

        self.called = {step for step, _, _ in calls}
        for step in steps:
            if step not in self.called:
                print(f"{step} is not called in {self.python_input_path}: skipped")
        for step, _, _ in calls:
            if step not in steps:
                raise SystemExit(f"{step} is called in {self.python_input_path} but is not in {self.yml_input_path}")

        # Global properties used in python `if` become workflow params, the rest go to every step
        flags = {flag: global_properties[flag] for _, _, step_flags in calls for flag in step_flags}
        block_properties = {k: v for k, v in global_properties.items() if k not in WORKFLOW_PROPERTIES and k not in flags}
        columns = self.getColumns({step: steps[step] for step, _, _ in calls})

        wf_steps = [self.getStep(step, tool, step_flags, tools, steps, columns, block_properties, descriptions.get(step, ""))
                    for step, tool, step_flags in calls]

        title = self.getTitle()
        context = {
            "mark": GENERATED_MARK,
            "title": title,
            "title_literal": NextflowGenerator.groovyValue(title),
            "wf_name": self.wf_path.name,
            "namespace": NAMESPACE,
            "nextflow_version": NEXTFLOW_VERSION,
            "steps": wf_steps,
            "columns": columns,
            "column_steps": {column: [step["name"] for step in wf_steps if value in (steps[step["name"]].get("paths") or {}).values()] for value, column in columns.items()},
            "flags": {flag: NextflowGenerator.groovyValue(value) for flag, value in flags.items()},
            "flag_types": {flag: "Boolean" if isinstance(value, bool) else "Integer" if isinstance(value, int) else "String" for flag, value in flags.items()},
            "flag_steps": {flag: [step["name"] for step in wf_steps if flag in step["flags"]] for flag in flags},
            "labels": sorted({step["module"]["label"] for step in wf_steps} & LABEL_COMMENTS.keys()),
            "mpi_steps": [step["name"] for step in wf_steps if MPI_PROPERTIES & (steps[step["name"]].get("properties") or {}).keys()],
            "label_comments": LABEL_COMMENTS,
        }

        # e2e test: every output of the steps run by default, under results/<id>/<step>/
        sample_id = self.getSampleId()
        settings = TEST_SETTINGS.get(self.wf_path.name, {})
        test_context = {
            **context,
            "sample_id": sample_id,
            "expected": [f"{sample_id}/{step['name']}/{sample_id}_{file}" for step in wf_steps
                         if all(flags[flag] for flag in step["flags"]) for file in step["files"]],
            "runtime": settings.get("runtime", []),
            "runtime_doc": ", ".join(settings.get("runtime", [])) + " (the python CI ones)" if settings.get("runtime") else "none",
            "attempts": settings.get("attempts", 1),
        }

        self.copyModules(wf_steps)
        self.copyInputs(columns)
        self.writeGenerated("main.nf", self.main_template.render(**context))
        self.writeGenerated("nextflow.config", self.config_template.render(**context))
        self.writeGenerated("README.md", self.readme_template.render(**context))
        self.writeGenerated(".gitignore", f"# {GENERATED_MARK}\nwork/\nresults/\n.nextflow/\n.nextflow.log*\n")
        # <wf>/tests/nextflow next to <wf>/nextflow
        self.writeGenerated("run_test.sh", self.test_template.render(**test_context), folder=self.output_path.parent.joinpath("tests", "nextflow"), executable=True)


def main():
    parser = argparse.ArgumentParser(description="Translates to Nextflow a given Python / YAML workflow.",
                                     formatter_class=lambda prog: argparse.RawTextHelpFormatter(prog, width=99999),
                                     epilog='Examples: \n'
                                            'nextflow_wf_generator.py -y path/to/yaml/workflow -p path/to/python/workflow -a path/to/biobb_adapters/nextflow -o path/to/nextflow/workflow\n'
                                            'nextflow_wf_generator.py --yml_in path/to/yaml/workflow --python_in path/to/python/workflow '
                                            '--adapters path/to/biobb_adapters/nextflow --output path/to/nextflow/workflow')
    required_args = parser.add_argument_group('required arguments')
    required_args.add_argument('--yml_in', '-y', required=True, help='Path to the original YAML file.')
    required_args.add_argument('--python_in', '-p', required=True, help='Path to the original Python file.')
    required_args.add_argument('--adapters', '-a', required=True, help='Path to the biobb_adapters Nextflow modules folder (biobb_adapters/biobb_adapters/nextflow).')
    required_args.add_argument('--output', '-o', required=True, help='Output path to the Nextflow workflow folder.')

    args = parser.parse_args()

    NextflowWFGenerator(yml_input_path=args.yml_in, python_input_path=args.python_in, adapters_path=args.adapters, output_path=args.output).launch()


if __name__ == '__main__':
    main()
